// Numbers and times as the watchlist writes them: prices with their own
// decimals and thousands grouped, a change always with its sign, and the
// moment a price is from in the frame's time zone (a JS app's Date is).

const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

/** The decimals a price is shown with: the source's own (4 for a currency
 * pair, 2 for a stock), fewer for a big number (Bitcoin's 59,243). */
export function decimalsFor(price: number, decimals: number): number {
  const size = Math.abs(price)
  if (size >= 10000) return 0
  if (size >= 1000) return Math.min(decimals, 2)
  return decimals
}

/** 1234.5 as "1,234.50" with `decimals` places. */
export function grouped(value: number, decimals: number): string {
  const fixed = Math.abs(value).toFixed(decimals)
  const dot = fixed.indexOf('.')
  const whole = dot < 0 ? fixed : fixed.slice(0, dot)
  const rest = dot < 0 ? '' : fixed.slice(dot)
  const withCommas = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',')
  return (value < 0 && Number(fixed) !== 0 ? '-' : '') + withCommas + rest
}

/** A price as it is shown: its decimals, grouped. */
export const priceText = (price: number, decimals: number) => grouped(price, decimalsFor(price, decimals))

/** A change in money, with its sign ("+2.96", "-0.0036"), in the price's decimals. */
export function changeText(change: number, price: number, decimals: number): string {
  const places = decimalsFor(price, decimals)
  const text = grouped(Math.abs(change), places)
  if (Number(Math.abs(change).toFixed(places)) === 0) return text
  return (change > 0 ? '+' : '-') + text
}

/** A change in percent with its sign: "+0.83%", "-12.40%", "0.00%". */
export function percentText(pct: number): string {
  const places = Math.abs(pct) >= 100 ? 0 : 2
  const text = Math.abs(pct).toFixed(places)
  if (Number(text) === 0) return `${text}%`
  return `${pct > 0 ? '+' : '-'}${text}%`
}

/** Up (1), down (-1) or unchanged (0), as the percent reads to two decimals. */
export function direction(pct: number): number {
  if (!Number.isFinite(pct)) return 0
  const shown = Math.round(pct * 100)
  return shown > 0 ? 1 : shown < 0 ? -1 : 0
}

const pad = (n: number) => String(n).padStart(2, '0')

/** "16:25", or "4:25 pm" on a 12-hour clock. */
export function clockText(ms: number, twelve: boolean): string {
  const d = new Date(ms)
  const h = d.getHours()
  return twelve ? `${h % 12 || 12}:${pad(d.getMinutes())} ${h < 12 ? 'am' : 'pm'}` : `${h}:${pad(d.getMinutes())}`
}

const startOfDay = (ms: number) => {
  const d = new Date(ms)
  return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
}

/** "27 Nov", with the year when it is not this year's ("27 Nov 2025"). */
export function dateText(ms: number, now: number): string {
  const d = new Date(ms)
  const year = d.getFullYear() !== new Date(now).getFullYear() ? ` ${d.getFullYear()}` : ''
  return `${d.getDate()} ${MONTHS[d.getMonth()]}${year}`
}

/** When a price is from, as short as it reads: "16:25" today, "Fri 22:00"
 * within the week, "27 Nov" before that. */
export function whenText(ms: number, now: number, twelve: boolean): string {
  const days = Math.round((startOfDay(now) - startOfDay(ms)) / 86400000)
  if (days === 0) return clockText(ms, twelve)
  if (days > 0 && days < 7) return `${DAY_NAMES[new Date(ms).getDay()]} ${clockText(ms, twelve)}`
  return dateText(ms, now)
}

/** A company's name without what every name has: "Apple Inc." is "Apple",
 * "ASML Holding N.V." "ASML", "Bitcoin USD" "Bitcoin". */
export function tidyName(name: string, type = '', currency = ''): string {
  const said = String(name || '').replace(/\s+/g, ' ').trim()
  let text = said
  if (type === 'CRYPTOCURRENCY' && currency) {
    text = text.replace(new RegExp(`\\s+${currency}$`, 'i'), '')
  }
  text = text.replace(/^the\s+/i, '')
  const suffix =
    /[\s,]+(inc\.?|incorporated|corporation|corp\.?|co\.?|company|ltd\.?|limited|plc|n\.v\.?|nv|s\.a\.?|sa|s\.p\.a\.?|ag|se|asa|ab|oyj|holdings?|group|class [a-c])$/i
  for (let i = 0; i < 3; i++) text = text.replace(suffix, '')
  text = text.replace(/[\s,.-]+$/, '').trim()
  return text || said
}

