// Friday 27 November 2026, the New York session: 14:30 to 18:00 UTC (a short day).
const OPEN = 1795789800 * 1000
const CLOSE = 1795802400 * 1000
const FRIDAY_NOON_NY = OPEN + 90 * 60 * 1000
// Saturday 28 November, 15:00 UTC: every stock market closed.
const SATURDAY = 1795878000 * 1000
const MINUTE = 60 * 1000

function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

// A Yahoo chart answer shaped as AAPL's, for the other symbols: daily closes
// up to Friday, the price, its change in percent and Friday's session.
function chart(symbol: string, o: { price: number; pct: number; closes: number[]; type?: string; name?: string; hint?: number }) {
  const stamps = o.closes.map((_, i) => 1795789800 - (o.closes.length - 1 - i) * 86400)
  return JSON.stringify({
    chart: {
      result: [{
        meta: {
          currency: 'USD', symbol, instrumentType: o.type || 'EQUITY', fullExchangeName: 'NYSE', regularMarketTime: 1795802401,
          gmtoffset: -18000, regularMarketPrice: o.price, regularMarketChangePercent: o.pct, shortName: o.name || symbol,
          priceHint: o.hint ?? 2, dataGranularity: '1d', range: '1mo',
          currentTradingPeriod: {
            pre: { start: 1795770000, end: 1795789800 }, regular: { start: 1795789800, end: 1795802400 },
            post: { start: 1795802400, end: 1795827600 },
          },
        },
        timestamp: stamps,
        indicators: { quote: [{ close: o.closes }] },
      }],
      error: null,
    },
  })
}

const BTC = chart('BTC-USD', { price: 59243.23, pct: -1.351, closes: [60494.71, 59866.37, 59243.23], type: 'CRYPTOCURRENCY', name: 'Bitcoin USD' })
const MSFT = chart('MSFT', { price: 492.85, pct: 0.596, closes: [496.13, 489.93, 492.85], name: 'Microsoft Corporation' })

// Answers Yahoo's chart requests from `answers` (a body, or a function for
// anything else), and 404 for a symbol it does not have.
function yahoo(answers: Record<string, any>) {
  return mock.httpRequest((url: string) => {
    const m = /\/v8\/finance\/chart\/([^?]+)\?/.exec(url)
    const answer = answers[m ? decodeURIComponent(m[1]) : '']
    if (answer === undefined) return mock.response(404, NOT_FOUND)
    if (typeof answer === 'function') return answer()
    return mock.response(200, answer)
  })
}

const options = (now: number, extra: Record<string, any> = {}) => ({
