})

describe('the symbols field', () => {
  it('reads commas, new lines, names after a bar, and each symbol once', () => {
    expect(parseSymbols('aapl, MSFT | Microsoft\n^GSPC;  btc-usd ,aapl, ,EURUSD=X')).toEqual([
      { symbol: 'AAPL', name: '' },
      { symbol: 'MSFT', name: 'Microsoft' },
      { symbol: '^GSPC', name: '' },
      { symbol: 'BTC-USD', name: '' },
      { symbol: 'EURUSD=X', name: '' },
    ])
    expect(parseSymbols('')).toEqual([])
    expect(parseSymbols(Array.from({ length: 20 }, (_, i) => `S${i}`).join(','))).toHaveLength(12)
  })
})

describe('Yahoo Finance', () => {
  it('reads the price, the change since the previous close and the month', () => {
    const item = parseYahoo('AAPL', mock.response(200, AAPL), SATURDAY)
    expect(item).toMatchObject({ symbol: 'AAPL', name: 'Apple', currency: 'USD', exchange: 'NasdaqGS', price: 358.54, pct: 0.832, decimals: 2 })
    expect(item.change).toBeCloseTo(2.96, 2)
    expect(item.closes).toHaveLength(22)
    expect(item.closes[0]).toBe(343.83)
    expect(item.closes[21]).toBe(358.54)
    expect(item.session).toEqual([1795770000000, OPEN, CLOSE, 1795827600000])
    expect(item).toMatchObject({ dayLow: 355.64, dayHigh: 359.5, yearLow: 243.42, yearHigh: 360.83 })
    expect(item.time).toBe(1795802401000)
  })

  it('takes the previous close it says, for a day of five-minute bars', () => {
    const item = parseYahoo('AAPL', mock.response(200, AAPL_TODAY), SATURDAY)
    expect(item.change).toBeCloseTo(2.96, 2)
    expect(item.pct).toBeCloseTo(0.832, 2)
    // The last bar ends at the price.
    expect(item.closes).toEqual([358.6, 358.7, 358.54])
  })

  it('says why a symbol did not come', () => {
    expect(() => parseYahoo('NOPE', mock.response(404, NOT_FOUND), SATURDAY)).toThrow('Unknown symbol')
    expect(() => parseYahoo('AAPL', mock.response(429, TOO_MANY), SATURDAY)).toThrow('limiting')
    expect(() => parseYahoo('AAPL', { status: 0, error: 'timeout' }, SATURDAY)).toThrow('No connection')
    expect(() => parseYahoo('AAPL', mock.response(502, '<html>'), SATURDAY)).toThrow('error 502')
  })

  it('asks for the closes alone, with the symbol in the path', () => {
    const http = yahoo({ '^GSPC': AAPL })
    update(null, [{ symbol: '^GSPC', name: '' }], options(SATURDAY))
    expect(http.calls[0][0]).toBe(
      'https://query1.finance.yahoo.com/v8/finance/chart/%5EGSPC?range=1mo&interval=1d&indicators=close&includeAdjustedClose=false',
    )
    expect(http.calls[0][1]).toEqual({ timeoutMs: 15000 })
  })
})

describe('Twelve Data', () => {
  it('reads a quote and its series', () => {
    const points = parseTwelveSeries(mock.response(200, TD_SERIES))
    expect(points.map((p) => p[1])).toEqual([354.070007, 355.57999, 358.54001])
    const item = parseTwelveQuote('AAPL', mock.response(200, TD_QUOTE), points, null, '1mo', SATURDAY)
    expect(item).toMatchObject({ name: 'Apple', price: 358.54001, decimals: 2, open: false, dayLow: 355.64001, yearHigh: 360.82999 })
    expect(item.change).toBeCloseTo(2.96, 2)
    expect(item.pct).toBeCloseTo(0.832, 2)
    expect(item.closes).toEqual([354.07, 355.58, 358.54])
  })

  it('asks a key first, and stops at one it refuses', () => {
    const none = update(null, [{ symbol: 'AAPL', name: '' }], options(SATURDAY, { source: 'twelvedata' }))
    expect(none.cache.problem).toMatch('API key')
    const http = mock.httpRequest(() => mock.response(401, TD_BAD_KEY))
    const refused = update(null, [{ symbol: 'AAPL', name: '' }, { symbol: 'EUR/USD', name: '' }], options(SATURDAY, { source: 'twelvedata', key: 'nope' }))
    expect(http.calls).toHaveLength(1)
    expect(refused.cache.errors).toEqual({ AAPL: 'Twelve Data refused the API key', 'EUR/USD': 'Twelve Data refused the API key' })
    expect(refused.cache.problem).toBe('Twelve Data refused the API key')
  })

  it('fetches a series only now and then, a quote every time', () => {
    const http = mock.httpRequest((url: string) => mock.response(200, url.includes('/quote') ? TD_QUOTE : TD_SERIES))
    const o = options(SATURDAY, { source: 'twelvedata', key: 'k' })
    const first = update(null, [{ symbol: 'AAPL', name: '' }], o)
    expect(http.calls.map((c) => c[0].split('?')[0])).toEqual(['https://api.twelvedata.com/time_series', 'https://api.twelvedata.com/quote'])
    expect(http.calls[0][0]).toMatch('symbol=AAPL&interval=1day&outputsize=22&timezone=UTC&apikey=k')
    update(first.cache, [{ symbol: 'AAPL', name: '' }], { ...o, now: SATURDAY + 61 * MINUTE })
    expect(http.calls).toHaveLength(3)
    expect(http.calls[2][0]).toMatch('/quote?')
  })
})

describe('when to ask', () => {
  it('every 15 minutes while a market is open, hourly when none is', () => {
    mock.log(() => {})
    yahoo({ AAPL, 'BTC-USD': BTC })
    const stocks = update(null, [{ symbol: 'AAPL', name: '' }], options(FRIDAY_NOON_NY)).cache
    expect(marketState(stocks.items.AAPL, FRIDAY_NOON_NY)).toBe('open')
    expect(secondsToNext(stocks, FRIDAY_NOON_NY, everyFor(3600))).toBe(900)
    expect(marketState(stocks.items.AAPL, SATURDAY)).toBe('closed')
    expect(secondsToNext(stocks, SATURDAY, everyFor(3600))).toBe(3600)
    // Crypto trades on Saturday too.
    const crypto = update(null, [{ symbol: 'BTC-USD', name: '' }], options(SATURDAY)).cache
    expect(marketState(crypto.items['BTC-USD'], SATURDAY)).toBe('open')
    expect(secondsToNext(crypto, SATURDAY, everyFor(3600))).toBe(900)
  })

  it('wakes a minute after the market opens and after it closes', () => {
    yahoo({ AAPL })
    const early = OPEN - 20 * MINUTE
    const cache = update(null, [{ symbol: 'AAPL', name: '' }], options(early)).cache
    expect(marketState(cache.items.AAPL, early)).toBe('pre')
    expect(secondsToNext(cache, early, everyFor(3600))).toBe(21 * 60)
    expect(isDue(cache, OPEN + MINUTE, everyFor(3600))).toBe(true)
    const late = CLOSE - 5 * MINUTE
    expect(secondsToNext({ ...cache, at: late }, late, everyFor(3600))).toBe(6 * 60)
    expect(marketState(cache.items.AAPL, CLOSE + MINUTE)).toBe('post')
  })

  it('asks nothing while the data is fresh, but a new symbol at once', () => {
    const http = yahoo({ AAPL, MSFT })
    const first = update(null, [{ symbol: 'AAPL', name: '' }], options(SATURDAY))
    expect(first.fetched).toBe(true)
    const again = update(first.cache, [{ symbol: 'AAPL', name: '' }], options(SATURDAY + 10 * MINUTE))
    expect(again.fetched).toBe(false)
    expect(http.calls).toHaveLength(1)
    const more = update(first.cache, [{ symbol: 'AAPL', name: '' }, { symbol: 'MSFT', name: '' }], options(SATURDAY + 10 * MINUTE))
    expect(http.calls).toHaveLength(2)
    expect(Object.keys(more.cache.items)).toEqual(['AAPL', 'MSFT'])
    // An hour on (a minute early is fine), everything again; a tap on Update any time.
    update(more.cache, [{ symbol: 'AAPL', name: '' }, { symbol: 'MSFT', name: '' }], options(SATURDAY + 59 * MINUTE))
    expect(http.calls).toHaveLength(4)
    update(more.cache, [{ symbol: 'AAPL', name: '' }], options(SATURDAY + 11 * MINUTE, { force: true }))
    expect(http.calls).toHaveLength(5)
  })
})

describe('when it fails', () => {
  it('keeps the last good data and says why', () => {
    mock.log(() => {})
    yahoo({ AAPL, MSFT })
    const good = update(null, [{ symbol: 'AAPL', name: '' }, { symbol: 'MSFT', name: '' }], options(SATURDAY)).cache
    // The network goes: two failures in a row are enough to stop asking.
    const http = mock.httpRequest(() => ({ status: 0, error: 'Connection refused' }))
    const wanted = [{ symbol: 'AAPL', name: '' }, { symbol: 'MSFT', name: '' }, { symbol: 'IBM', name: '' }]
    const offline = update(good, wanted, options(SATURDAY + 2 * 3600 * 1000)).cache
    expect(http.calls).toHaveLength(2)
    expect(offline.items.AAPL.price).toBe(358.54)
    expect(offline.errors).toEqual({ AAPL: 'No connection', MSFT: 'No connection', IBM: 'No connection' })
    expect(offline.problem).toBe('No connection')
    expect(offline.ok).toBe(SATURDAY)
  })

  it('stops at a rate limit, and an unknown symbol is that row\'s alone', () => {
    mock.log(() => {})
    const limited = mock.httpRequest(() => mock.response(429, TOO_MANY))
    const cache = update(null, [{ symbol: 'AAPL', name: '' }, { symbol: 'MSFT', name: '' }], options(SATURDAY)).cache
    expect(limited.calls).toHaveLength(1)
    expect(cache.errors.MSFT).toBe('Yahoo Finance is limiting requests')
    expect(cache.problem).toBe('Yahoo Finance is limiting requests')
    yahoo({ AAPL })
    const typo = update(null, [{ symbol: 'AAPL', name: '' }, { symbol: 'APPL', name: '' }], options(SATURDAY)).cache
    expect(typo.errors).toEqual({ APPL: 'Unknown symbol' })
    expect(typo.problem).toBe('')
  })

  it('reads a kept field as an object or as its JSON, and nothing else', () => {
    yahoo({ AAPL })
    const cache = update(null, [{ symbol: 'AAPL', name: '' }], options(SATURDAY)).cache
    expect(readCache(JSON.stringify(cache))?.items.AAPL.price).toBe(358.54)
    expect(readCache(cache)?.ok).toBe(SATURDAY)
    expect(readCache('')).toBeNull()
    expect(readCache({ some: 'thing' })).toBeNull()
  })
})

describe('the scene', () => {
  it('draws the list, keeps the quotes and sleeps by the market', () => {
    const http = yahoo({ AAPL, MSFT, 'BTC-USD': BTC })
    const app = makeApp({ state: { symbols: 'AAPL, MSFT', refreshInterval: 3600 } })
    const ui = at(SATURDAY, () => get(app, makeContext()))
    expect(ui).toMatchObject({ type: 'div' })
    expect(http.calls).toHaveLength(2)
    expect(Object.keys(app.state.quotes.items)).toEqual(['AAPL', 'MSFT'])
    expect(app.nextSleep).toBe(3600)
    // A render from a tap within the hour asks nothing.
    at(SATURDAY + 5 * MINUTE, () => get(app, makeContext()))
    expect(http.calls).toHaveLength(2)
    // With crypto in the list it is every 15 minutes.
    const crypto = makeApp({ state: { symbols: 'BTC-USD' } })
    at(SATURDAY, () => get(crypto, makeContext()))
    expect(crypto.nextSleep).toBe(900)
  })

  it('draws every panel shape: small, round, tall, a big one and the big view', () => {
    yahoo({ AAPL, MSFT })
    const sizes = [[240, 320], [480, 800], [1200, 1600], [466, 466]]
    for (const [width, height] of sizes) {
      const app = makeApp({ state: { symbols: 'AAPL, MSFT, NOPE' }, frame: { width, height, paper: width === 1200, color: true } })
      const ui = at(SATURDAY, () => get(app, makeContext({ round: width === 466 })))
      expect(ui).toMatchObject({ type: 'div' })
      const one = makeApp({ state: { symbols: 'AAPL' }, frame: { width, height, color: false } })
      expect(at(SATURDAY, () => get(one, makeContext({ round: width === 466 })))).toMatchObject({ type: 'div' })
    }
  })

  it('leaves the big view on Back', () => {
    const app = makeApp()
    expect(onEvent(app, { event: 'back' })).toBe(false)
    frameos.remember('focus', 'AAPL')
    expect(onEvent(app, { event: 'back' })).toBe(true)
    expect(frameos.recall('focus')).toBeUndefined()
  })
})

describe('numbers and times', () => {
  it('writes prices, changes and percents with their signs', () => {
    expect(priceText(358.54, 2)).toBe('358.54')
    expect(priceText(7297.49, 2)).toBe('7,297.49')
    expect(priceText(59243.23, 2)).toBe('59,243')
    expect(priceText(1.09391, 4)).toBe('1.0939')
    expect(changeText(2.9584, 358.54, 2)).toBe('+2.96')
    expect(changeText(-0.0036, 1.0939, 4)).toBe('-0.0036')
    expect(changeText(-811.4, 59243.23, 2)).toBe('-811')
    expect(changeText(0.001, 358.54, 2)).toBe('0.00')
    expect(percentText(0.832)).toBe('+0.83%')
    expect(percentText(-1.351)).toBe('-1.35%')
    expect(percentText(0.001)).toBe('0.00%')
    expect(percentText(150.4)).toBe('+150%')
  })

  it('says when, as short as it reads', () => {
    const now = new Date(2026, 10, 28, 16, 0).getTime()
    expect(whenText(new Date(2026, 10, 28, 9, 5).getTime(), now, false)).toBe('9:05')
    expect(whenText(new Date(2026, 10, 27, 22, 0).getTime(), now, false)).toBe('Fri 22:00')
    expect(whenText(new Date(2026, 10, 27, 22, 0).getTime(), now, true)).toBe('Fri 10:00 pm')
    expect(whenText(new Date(2026, 10, 2, 22, 0).getTime(), now, false)).toBe('2 Nov')
  })

  it('tidies names', () => {
    expect(tidyName('Apple Inc.')).toBe('Apple')
    expect(tidyName('Microsoft Corporation')).toBe('Microsoft')
    expect(tidyName('ASML Holding N.V.')).toBe('ASML')
    expect(tidyName('Meta Platforms, Inc.')).toBe('Meta Platforms')
    expect(tidyName('The Walt Disney Company')).toBe('Walt Disney')
    expect(tidyName('Bitcoin USD', 'CRYPTOCURRENCY', 'USD')).toBe('Bitcoin')
    expect(tidyName('S&P 500')).toBe('S&P 500')
    expect(tidyName('Group')).toBe('Group')
  })
})
